1	export const EVAL_STORAGE_KEY = 'flowguard_facial_evaluation_records';
2	export const EVAL_RECORDS_UPDATED_EVENT = 'flowguard:evaluation-records-updated';
3	export const EVAL_LABEL_MAP_KEY = 'flowguard_facial_evaluation_label_map';
4	export const SIM_USERS_KEY = 'flowguard_facial_simulation_users';
5	export const ACCESS_EVAL_STORAGE_KEY = 'flowguard_access_evaluation_records';
6	
7	// Legacy simulated CRUD fixtures only; production classes come from PostgreSQL.
8	export const ENROLLED_LABELS = ['P01', 'P02', 'P03', 'P04', 'P05'];
9	export const UNKNOWN_LABEL = 'Unknown';
10	export const IDENTITY_LABELS = [...ENROLLED_LABELS, UNKNOWN_LABEL];
11	export const NO_FACE = 'No Face';
12	export const DETECTION_OUTCOMES = { NO_FACE: 'NO_FACE' };
13	
14	export const CONDITIONS = ['Front', 'Left Angle', 'Right Angle', 'Normal Lighting', 'Low Lighting', 'Glasses', 'Other'];
15	export const SOURCES = ['Live', 'Simulated'];
16	export const ORIGINS = ['Manual', 'Gate Scanner', 'V-Patrol', 'Live Model Evaluation', 'Image-Based Evaluation', 'Simulated CRUD'];
17	export const LEGACY_CONDITION_MAP = {
18	  front: 'Front',
19	  left: 'Left Angle',
20	  right: 'Right Angle',
21	  'normal-light': 'Normal Lighting',
22	  'low-light': 'Low Lighting'
23	};
24	
25	const defaultStorage = () => (typeof window !== 'undefined' ? window.localStorage : null);
26	const safeJson = (raw, fallback) => {
27	  try {
28	    const parsed = raw ? JSON.parse(raw) : fallback;
29	    return parsed ?? fallback;
30	  } catch {
31	    return fallback;
32	  }
33	};
34	
35	export function normalizeCondition(condition = 'Front') {
36	  return LEGACY_CONDITION_MAP[condition] || condition || 'Front';
37	}
38	
39	export const isEvaluationLabel = (label) => /^P\d+$/.test(String(label || ''));
40	export const evaluationLabelNumber = (label) => { const match = /^P(\d+)$/.exec(String(label || '')); return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER; };
41	export const sortEvaluationLabels = (labels = []) => [...new Set(labels.filter(isEvaluationLabel))].sort((a, b) => evaluationLabelNumber(a) - evaluationLabelNumber(b));
42	export function normalizeLabel(label) { if (label === NO_FACE) return NO_FACE; return label === UNKNOWN_LABEL || isEvaluationLabel(label) ? label : UNKNOWN_LABEL; }
43	export function matrixLabelsForRecords(records = [], participantLabels = []) { const historical = records.flatMap((r) => [r.actualLabel, r.predictedLabel]); return [...sortEvaluationLabels([...participantLabels, ...historical]), UNKNOWN_LABEL]; }
44	
45	export function loadRecords(storage = defaultStorage()) {
46	  if (!storage) return [];
47	  const parsed = safeJson(storage.getItem(EVAL_STORAGE_KEY), []);
48	  return Array.isArray(parsed) ? parsed.map(sanitizeRecord).filter(Boolean) : [];
49	}
50	
51	export function saveRecords(records, storage = defaultStorage()) {
52	  if (!storage) return;
53	  storage.setItem(EVAL_STORAGE_KEY, JSON.stringify(records.map(sanitizeRecord).filter(Boolean)));
54	}
55	
56	export function loadLabelMap(storage = defaultStorage()) {
57	  if (!storage) return {};
58	  const parsed = safeJson(storage.getItem(EVAL_LABEL_MAP_KEY), {});
59	  return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
60	}
61	
62	export function saveLabelMap(map, storage = defaultStorage()) {
63	  if (!storage) return;
64	  const clean = {};
65	  Object.entries(map || {}).forEach(([userId, label]) => {
66	    if (ENROLLED_LABELS.includes(label)) clean[String(userId)] = label;
67	  });
68	  storage.setItem(EVAL_LABEL_MAP_KEY, JSON.stringify(clean));
69	}
70	
71	export function labelForUserId(userId, map = loadLabelMap()) {
72	  if (userId == null) return null;
73	  return map[String(userId)] || null;
74	}
75	
76	export function assignLabel(map, userId, label) {
77	  if (!userId || !ENROLLED_LABELS.includes(label)) throw new Error('Choose an enrolled user and a P01-P05 label.');
78	  const next = { ...(map || {}) };
79	  const duplicate = Object.entries(next).find(([existingUserId, existingLabel]) => existingUserId !== String(userId) && existingLabel === label);
80	  if (duplicate) throw new Error(`${label} is already assigned. Remove it before reusing the label.`);
81	  next[String(userId)] = label;
82	  return next;
83	}
84	
85	export function removeMappedUser(map, userId) {
86	  const next = { ...(map || {}) };
87	  delete next[String(userId)];
88	  return next;
89	}
90	
91	let idSeq = 0;
92	export function createRecord({
93	  actualLabel,
94	  predictedLabel,
95	  confidence = null,
96	  condition = 'Front',
97	  latencyMs = null,
98	  source = 'Simulated',
99	  origin = source === 'Live' ? 'Manual' : 'Simulated CRUD',
100	  notes = '',
101	  detectionOutcome = null,
102	  timestamp = new Date().toISOString()
103	}) {
104	  idSeq += 1;
105	  const isNoFace = detectionOutcome === DETECTION_OUTCOMES.NO_FACE || actualLabel === NO_FACE || predictedLabel === NO_FACE;
106	  return sanitizeRecord({
107	    id: `EV-${Date.now().toString(36)}-${idSeq}`,
108	    actualLabel: isNoFace ? null : normalizeLabel(actualLabel),
109	    predictedLabel: isNoFace ? null : normalizeLabel(predictedLabel),
110	    confidence: confidence == null || confidence === '' ? null : Number(confidence),
111	    condition: normalizeCondition(condition),
112	    latencyMs: latencyMs == null || latencyMs === '' ? null : Math.round(Number(latencyMs)),
113	    source: SOURCES.includes(source) ? source : 'Simulated',
114	    origin: origin || 'Manual',
115	    notes: String(notes || '').slice(0, 500),
116	    detectionOutcome: isNoFace ? DETECTION_OUTCOMES.NO_FACE : null,
117	    timestamp
118	  });
