201	    const actual = normalizeLabel(r.actualLabel);
202	    const predicted = normalizeLabel(r.predictedLabel);
203	    if (idx[actual] == null || idx[predicted] == null) continue;
204	    matrix[idx[actual]][idx[predicted]] += 1;
205	    identityRecords.push({ ...r, actualLabel: actual, predictedLabel: predicted });
206	  }
