213	  const perClass = labels.map((label, i) => {
214	    const tp = matrix[i][i];
215	    const actualTotal = matrix[i].reduce((a, b) => a + b, 0);
216	    const predictedTotal = matrix.reduce((sum, row) => sum + row[i], 0);
