306	    actualAuthorization: record.actualAuthorization,
307	    predictedDecision: Object.values(ACCESS_DECISIONS).includes(record.predictedDecision) ? record.predictedDecision : null,
308	    reason: String(record.reason || '').slice(0, 120), actualLabel: normalizeLabel(record.actualLabel),
309	    predictedLabel: normalizeLabel(record.predictedLabel), confidence: record.confidence == null ? null : Number(record.confidence),
