314	export const createAccessEvaluationRecord = (input) => sanitizeAccessEvaluationRecord({ ...input, id: `AE-${Date.now().toString(36)}-${++idSeq}` });
315	export function loadAccessEvaluationRecords(storage = defaultStorage()) { if (!storage) return []; const parsed = safeJson(storage.getItem(ACCESS_EVAL_STORAGE_KEY), []); return Array.isArray(parsed) ? parsed.map(sanitizeAccessEvaluationRecord).filter(Boolean) : []; }
316	export function saveAccessEvaluationRecords(records, storage = defaultStorage()) { if (storage) storage.setItem(ACCESS_EVAL_STORAGE_KEY, JSON.stringify((records || []).map(sanitizeAccessEvaluationRecord).filter(Boolean))); }
317	export function computeAccessDecisionMatrix(records = []) {
318	  const matrix = [[0, 0], [0, 0]]; let noDecisionCount = 0;
319	  records.forEach((r) => { const row = r.actualAuthorization === ACTUAL_AUTHORIZATION.AUTHORIZED ? 0 : r.actualAuthorization === ACTUAL_AUTHORIZATION.UNAUTHORIZED ? 1 : -1; const col = r.predictedDecision === ACCESS_DECISIONS.GRANTED ? 0 : r.predictedDecision === ACCESS_DECISIONS.DENIED ? 1 : -1; if (row < 0) return; if (col < 0) noDecisionCount += 1; else matrix[row][col] += 1; });
320	  const trueGrants = matrix[0][0], falseDenials = matrix[0][1], falseGrants = matrix[1][0], trueDenials = matrix[1][1];
321	  const sampleCount = trueGrants + falseDenials + falseGrants + trueDenials, correctCount = trueGrants + trueDenials;
322	  return { matrix, sampleCount, correctCount, accuracy: safeDiv(correctCount, sampleCount), trueGrants, falseDenials, falseGrants, trueDenials, falseGrantRate: safeDiv(falseGrants, falseGrants + trueDenials), falseDenialRate: safeDiv(falseDenials, falseDenials + trueGrants), noDecisionCount };
323	}
