1	import React from 'react';
2	import FaceRetouchingOffIcon from '@mui/icons-material/FaceRetouchingOff';
3	import VerifiedUserIcon from '@mui/icons-material/VerifiedUser';
4	import BlockIcon from '@mui/icons-material/Block';
5	import ReportProblemIcon from '@mui/icons-material/ReportProblem';
6	import { Link } from 'react-router-dom';
7	import SafeMuiIcon from './SafeMuiIcon';
8	import '../css/RecognitionDecisionCard.css';
9	
10	export const DECISION_STATES = {
11	  NO_FACE: 'NO_FACE',
12	  GRANTED: 'GRANTED',
13	  SUSPENDED: 'SUSPENDED',
14	  UNKNOWN: 'UNKNOWN'
